#### 🗃️ `prisma/schema.prisma`

```prisma
generator client {
  provider = "prisma-client-js"
}

datasource db {
  provider = "postgresql"
  url      = env("DATABASE_URL")
}

/*
  Domain Entities
*/
model User {
  id           Int      @default(autoincrement()) @id
  email        String   @unique
  hashedPwd    String
  role         Role     @default(CUSTOMER)
  createdAt    DateTime @default(now())
  updatedAt    DateTime @updatedAt
}

enum Role { ADMIN CUSTOMER }

model Truck {
  id              Int                @default(autoincrement()) @id
  licensePlate    String             @unique
  make            String?
  model           String?
  year            Int?
  capacityTonnes Float?
  status          Status             @default(ACTIVE)
  currentLocation Location?
  assignments     Assignment[]
  maintenances    Maintenance[]

  @@index([licensePlate])
}

enum Status { ACTIVE INACTIVE UNDER_MAINTENANCE }

model Driver {
  id          Int          @default(autoincrement()) @id
  firstName   String
  lastName    String
  phoneNumber String
  licenceNo   String       @unique
  assignedTo  Truck?       @relation(fields:[truckId], references:[id]) 
  truckId     Int?

  @@index([licenceNo])
}

model Shipment {
  id                 Int          @default(autoincrement()) @id
  description        String
  pickupAddress      String
  deliveryAddress    String
  scheduledPickup    DateTime
  scheduledDelivery  DateTime
  actualPickup       DateTime?
  actualDelivery     DateTime?
  status             ShipmentStatus @default(PENDING)
  assignedTruck      Truck?        @relation(fields:[truckId], references:[id])
  truckId            Int?
  assignedDriver     Driver?       @relation(fields:[driverId], references:[id])
  driverId           Int?
  createdBy          User?         @relation(fields:[createdById], references:[id])
  createdById        Int?
  createdAt          DateTime      @default(now())

  @@index([status])
}

enum ShipmentStatus { PENDING ASSIGNED IN_TRANSIT DELIVERED CANCELLED }

model Maintenance {
  id          Int      @default(autoincrement()) @id
  truck       Truck    @relation(fields:[truckId], references:[id])
  truckId     Int
  issueDesc   String
  reportedOn  DateTime @default(now())
  resolvedOn  DateTime?
  status      MaintStatus @default(REPORTED)
}

enum MaintStatus { REPORTED RESOLVED CLOSED }

/*
  Helper tables
*/
model Location {
  id        Int      @default(autoincrement()) @id
  lat       Double
  lng       Double
  address   String?
  truck     Truck?   @relation(fields:[truckId], references:[id])
  truckId   Int?
}
```

Run migrations:

```bash
npx prisma migrate dev --name init
```

