#### 🎯 Sample Routes & Controllers

##### `/routes/shipment.routes.ts`

```ts
import express from 'express';
import { getShipments, createShipment, assignTrip } from '../controllers/shipment.controller';
import { authenticate } from '../middleware/auth';

const router = express.Router();

/* Public */
router.get('/', getShipments);

/* Protected */
router.post('/',
  authenticate,
  createShipment);

router.put('/:id/assign', authenticate, assignTrip);

export default router;
```

##### `/controllers/shipment.controller.ts`

```ts
import { Request, Response } from 'express';
import { prisma } from '../db';

/* List all shipments (paginated optional) */
export async function getShipments(req: Request, res: Response) {
  const page = Number(req.query.page ?? 1);
  const limit = Number(req.query.limit ?? 25);
  const skip = (page - 1) * limit;

  const [shipments, total] = await Promise.all([
    prisma.shipment.findMany({
      take: limit,
      skip,
      orderBy: [{ scheduledPickup: 'asc' }],
      include: { assignedTruck:true, assignedDriver:true }
    }),
    prisma.shipment.count()
  ]);

  res.send({ shipments, meta:{total,page,limit}});
}

/* Create a new shipment */
export async function createShipment(req: Request, res: Response) {
  const { description,pickupAddress,deliveryAddress,scheduledPickup,scheduledDelivery } = req.body;
  const user = (req as any).currentUser;

  const shipment = await prisma.shipment.create({
    data:{
      description,
      pickupAddress,
      deliveryAddress,
      scheduledPickup:new Date(scheduledPickup),
      scheduledDelivery:new Date(scheduledDelivery),
      createdBy:user
    }
  });

  res.status(201).send(shipment);
}

/* Assign a trip (truck + driver) */
export async function assignTrip(req: Request, res: Response){
  const { truckId, driverId } = req.body;
  const shipmentId = Number(req.params.id);

  /* Business rule check omitted for brevity */

  const updated = await prisma.shipment.update({
    where:{id:shipmentId},
    data:{
      assignedTruck:{connect:{id:truckId}},
      assignedDriver:{connect:{id:driverId}},
      status:'ASSIGNED'
    }
  });

  res.send(updated);
}
```

Similar patterns apply to Trucks, Drivers, Maintenance, etc. Keep them thin – move heavy logic to Services.

