#### 🔑 `hooks/useAuth.ts`

```tsx
import { useState, useEffect } from 'react';
import { setToken } from '@/api/api.client';

export interface IUser{ id:number,email:string,role:string }

export function useAuth(){
  const [user,setUser]=useState<IUser|null>(null);
  const [loading,setLoading]=useState(true);

  useEffect(()=>{
    const stored=localStorage.getItem('jwt');
    if(stored){
      setToken(stored);
      fetchMe(); // call /me endpoint
    }else setLoading(false);
  },[]);

  async function fetchMe(){/*call /users/me*/}

  async function login(email,password){
    const r=await api.post('/login',{email,password});
    localStorage.setItem('jwt',r.data.token);setToken(r.data.token);
    setUser(r.data.user);
  }

  function logout(){
    localStorage.removeItem('jwt');delete api.defaults.headers.Authorization;
    setUser(null);
  }

  return {user, loading, login, logout };
}
```

Wrap `<App>` inside `<AuthProvider/>`.

