#### 📄 Page Example – `pages/ShipmentsList.tsx`

```tsx
import { useQuery } from '@tanstack/react-query';
import { api } from '@/api/api.client';
import ShipmentCard from '@/components/ShipmentCard';

function ShipmentsList() {
  const {data, isLoading, refetch}=useQuery(['shipments'],()=>api.get('/shipments').then(res=>res.data));

  if(isLoading)return <p>Loading…</p>;

  return (
    <>
      <h2>Your Shipments</h2>
      <div className='grid grid-cols-1 md:grid-cols-2 gap-4'>
        {(data?.shipments||[]).map((sh:any)=>(
          <ShipmentCard key={sh.id} {...sh}/>
        ))}
      </div>
    </>
  );
}

export default ShipmentsList;
```

`ShipmentCard` shows brief details and “Assign” button which opens modal to pick truck/driver.

